functions._cdlHash:
function _cdlHash(s) {
  // djb2 — stable short hash for baseline identity (not cryptographic).
  var str = String(s == null ? "" : s), h = 5381, i = str.length;
  while (i) { h = (h * 33) ^ str.charCodeAt(--i); }
  return "h" + (h >>> 0).toString(16);
}

functions._cdlTokenize:
function _cdlTokenize(s) {
  // Lossless: captures whitespace runs AND non-whitespace runs separately,
  // so joining the tokens reproduces the input EXACTLY (needed for the diff
  // to be reconstructable byte-for-byte).
  var m = String(s == null ? "" : s).match(/\s+|\S+/g);
  return m || [];
}

functions._cdlSimilarity:
function _cdlSimilarity(a, b) {
  // Multiset Dice over normalized word tokens. 1 = identical word bag.
  var ta = _cdlNormalize(a).split(" ").filter(Boolean);
  var tb = _cdlNormalize(b).split(" ").filter(Boolean);
  if (!ta.length && !tb.length) return 1;
  if (!ta.length || !tb.length) return 0;
  var bag = {}, i, inter = 0;
  for (i = 0; i < tb.length; i++) bag[tb[i]] = (bag[tb[i]] || 0) + 1;
  for (i = 0; i < ta.length; i++) {
    if (bag[ta[i]] > 0) { inter++; bag[ta[i]]--; }
  }
  return (2 * inter) / (ta.length + tb.length);
}

functions._cdlHeading:
function _cdlHeading(t) {
  var firstLine = String(t == null ? "" : t).split("\n")[0];
  var m = firstLine.match(/^\s*((?:Article|Section|Exhibit|Schedule)?\s*\d+(?:\.\d+)*)[\.\)\s]/i);
  var num = m ? m[1].replace(/\s+/g, " ").trim() : "";
  var words = firstLine.trim().split(/\s+/).slice(0, 9).join(" ");
  if (words.length > 64) words = words.slice(0, 64) + "…";
  return (num && words.toLowerCase().indexOf(num.toLowerCase()) !== 0)
    ? num + " · " + words
    : (words || "(untitled clause)");
}

functions._cdlSegment:
function _cdlSegment(text) {
  // Heuristic clause segmentation for the test bench: split on blank lines.
  // The real system will segment via the indexer's section map.
  var raw = String(text == null ? "" : text).replace(/\r\n/g, "\n").replace(/\r/g, "\n");
  var blocks = raw.split(/\n[ \t]*\n+/);
  var out = [];
  blocks.forEach(function (b) {
    var t = b.replace(/^\s+|\s+$/g, "");
    if (t) out.push({ idx: out.length, text: t, heading: _cdlHeading(t) });
  });
  return out;
}

functions._cdlWordDiff:
function _cdlWordDiff(a, b) {
  // LCS token diff → [{op:'eq'|'del'|'ins', text}]. Lossless: eq+ins rebuilds
  // b exactly; eq+del rebuilds a exactly.
  var A = _cdlTokenize(a), B = _cdlTokenize(b);
  var n = A.length, m = B.length;
  // Guard against pathological O(n*m) on an un-segmented giant block.
  if (n * m > 4000000) {
    var coarse = [];
    if (a) coarse.push({ op: "del", text: a });
    if (b) coarse.push({ op: "ins", text: b });
    coarse._coarse = true;
    return coarse;
  }
  var dp = [], i, j;
  for (i = 0; i <= n; i++) {
    var row = new Array(m + 1);
    for (j = 0; j <= m; j++) row[j] = 0;
    dp.push(row);
  }
  for (i = n - 1; i >= 0; i--) {
    for (j = m - 1; j >= 0; j--) {
      dp[i][j] = (A[i] === B[j]) ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }
  var ops = [], ii = 0, jj = 0;
  function push(op, text) {
    var last = ops[ops.length - 1];
    if (last && last.op === op) last.text += text;
    else ops.push({ op: op, text: text });
  }
  while (ii < n && jj < m) {
    if (A[ii] === B[jj]) { push("eq", A[ii]); ii++; jj++; }
    else if (dp[ii + 1][jj] >= dp[ii][jj + 1]) { push("del", A[ii]); ii++; }
    else { push("ins", B[jj]); jj++; }
  }
  while (ii < n) { push("del", A[ii]); ii++; }
  while (jj < m) { push("ins", B[jj]); jj++; }
  return ops;
}

functions._cdlReconstruct:
function _cdlReconstruct(ops) {
  // Rebuild the FINAL text from a diff: keep eq + ins, drop del.
  var out = "";
  (ops || []).forEach(function (o) { if (o.op === "eq" || o.op === "ins") out += o.text; });
  return out;
}

functions._cdlDiffStats:
function _cdlDiffStats(ops) {
  var ins = 0, del = 0, eq = 0;
  (ops || []).forEach(function (o) {
    var n = _cdlTokenize(o.text).filter(function (t) { return /\S/.test(t); }).length;
    if (o.op === "ins") ins += n; else if (o.op === "del") del += n; else eq += n;
  });
  return { insertedTokens: ins, deletedTokens: del, keptTokens: eq };
}

functions._cdlAlign:
function _cdlAlign(origArr, finalArr, threshold) {
  threshold = (typeof threshold === "number") ? threshold : 0.4;
  var usedOrig = {}, slots = [];
  finalArr.forEach(function (fc) {
    var bestI = -1, bestScore = 0;
    for (var i = 0; i < origArr.length; i++) {
      if (usedOrig[i]) continue;
      var sc = _cdlSimilarity(origArr[i].text, fc.text);
      if (sc > bestScore) { bestScore = sc; bestI = i; }
    }
    if (bestI >= 0 && bestScore >= threshold) {
      usedOrig[bestI] = true;
      var oc = origArr[bestI];
      var identical = _cdlNormalize(oc.text) === _cdlNormalize(fc.text);
      slots.push({
        state: identical ? "unchanged" : "modified",
        origIdx: oc.idx, finalIdx: fc.idx,
        origText: oc.text, finalText: fc.text,
        heading: fc.heading || oc.heading, similarity: bestScore,
      });
    } else {
      slots.push({
        state: "added", origIdx: null, finalIdx: fc.idx,
        origText: "", finalText: fc.text, heading: fc.heading, similarity: 0,
      });
    }
  });
  origArr.forEach(function (oc, i) {
    if (!usedOrig[i]) {
      slots.push({
        state: "omitted", origIdx: oc.idx, finalIdx: null,
        origText: oc.text, finalText: "", heading: oc.heading, similarity: 0,
      });
    }
  });
  return slots;
}

functions._cdlBuildRecord:
function _cdlBuildRecord(slot, ctx) {
  // The durable, storable shape. Tiered: unchanged → pointer-ish; modified →
  // lossless diff; added → full text (Tier 2); omitted → near-empty signal.
  var rec = {
    id: "cdl_" + ctx.sessionTs + "_" + ctx.idx,
    tool: "clause_diff_lab",
    state: slot.state,
    heading: slot.heading || "",
    similarity: Number((slot.similarity || 0).toFixed(3)),
    provenance: {
      toolVersion: ctx.toolVersion || "test",
      kernelVersion: ctx.kernelVersion || "",
      timestamp: ctx.timestamp,
    },
  };
  if (slot.state === "unchanged") {
    rec.baselineHash = _cdlHash(_cdlNormalize(slot.origText));
  } else if (slot.state === "modified") {
    rec.baselineHash = _cdlHash(_cdlNormalize(slot.origText));
    rec.diffOps = _cdlWordDiff(slot.origText, slot.finalText);
    rec.diffStats = _cdlDiffStats(rec.diffOps);
  } else if (slot.state === "added") {
    rec.finalText = slot.finalText; // no baseline → store full text
  } else if (slot.state === "omitted") {
    rec.baselineHash = _cdlHash(_cdlNormalize(slot.origText));
  }
  // Test-only scaffolding — the raw clause text kept so the redline view can
  // render. In the real system this stays LOCAL and is not shared. Marked
  // under _test to make clear it is not part of the durable record shape.
  rec._test = { origText: slot.origText, finalText: slot.finalText };
  return rec;
}

functions._cdlAnalyze:
function _cdlAnalyze(origText, finalText, ctx) {
  ctx = ctx || {};
  var origArr = _cdlSegment(origText);
  var finalArr = _cdlSegment(finalText);
  var slots = _cdlAlign(origArr, finalArr, ctx.threshold);
  var records = slots.map(function (slot, i) {
    return _cdlBuildRecord(slot, {
      sessionTs: ctx.sessionTs, idx: i,
      toolVersion: ctx.toolVersion, kernelVersion: ctx.kernelVersion,
      timestamp: ctx.timestamp,
    });
  });
  var counts = { unchanged: 0, modified: 0, added: 0, omitted: 0 };
  slots.forEach(function (s) { counts[s.state]++; });
  return {
    items: records, slots: slots, counts: counts,
    origCount: origArr.length, finalCount: finalArr.length,
    overview: origArr.length + " original / " + finalArr.length + " final clauses · " +
      counts.modified + " modified, " + counts.added + " added, " +
      counts.omitted + " omitted, " + counts.unchanged + " unchanged",
    provenance: { timestamp: ctx.timestamp, kernelVersion: ctx.kernelVersion, toolVersion: ctx.toolVersion },
  };
}

// ─── Redline rendering (inline styles for guaranteed paint) ─────────────

functions._cdlRenderOps:
function _cdlRenderOps(ops) {
  var DEL = "text-decoration:line-through;color:#b3261e;background:#fde8e6;border-radius:2px;";
  var INS = "text-decoration:underline;color:#0b6b3a;background:#e6f4ea;border-radius:2px;";
  var html = "";
  (ops || []).forEach(function (o) {
    var t = _cdlEsc(o.text);
    if (o.op === "del") html += '<span style="' + DEL + '">' + t + "</span>";
    else if (o.op === "ins") html += '<span style="' + INS + '">' + t + "</span>";
    else html += t;
  });
  return html;
}

functions._cdlRenderRedline:
function _cdlRenderRedline(rec) {
  if (rec.state === "unchanged") {
    return '<div class="_cdl_note _cdl_note_ok">✓ Identical to original — matches baseline (' +
      _cdlEsc(rec.baselineHash) + "), stored as a pointer only.</div>";
  }
  if (rec.state === "added") {
    var insStyle = "text-decoration:underline;color:#0b6b3a;background:#e6f4ea;border-radius:2px;";
    return '<div class="_cdl_note _cdl_note_add">＋ Counterparty-added — no baseline. Stored as full text (Tier 2).</div>' +
      '<div class="_cdl_redline"><span style="' + insStyle + '">' +
      _cdlEsc(rec._test.finalText) + "</span></div>";
  }
  if (rec.state === "omitted") {
    var delStyle = "text-decoration:line-through;color:#b3261e;background:#fde8e6;border-radius:2px;";
    return '<div class="_cdl_note _cdl_note_del">－ In original, omitted from final. Stored as a near-empty signal.</div>' +
      '<div class="_cdl_redline"><span style="' + delStyle + '">' +
      _cdlEsc(rec._test.origText) + "</span></div>";
  }
  // modified
  var recon = _cdlReconstruct(rec.diffOps);
  var ok = (recon === rec._test.finalText);
  var badge = ok
    ? '<span class="_cdl_recon _cdl_recon_ok">✓ Reconstruct matches final</span>'
    : '<span class="_cdl_recon _cdl_recon_bad">✗ Reconstruct MISMATCH</span>';
  var coarse = rec.diffOps && rec.diffOps._coarse
    ? '<div class="_cdl_note _cdl_note_warn">⚠ Clause too large for token diff — stored as whole replace.</div>' : "";
  return coarse +
    '<div class="_cdl_redline">' + _cdlRenderOps(rec.diffOps) + "</div>" +
    '<div class="_cdl_reconrow">' + badge +
    ' <span class="_cdl_dim">' + rec.diffStats.insertedTokens + " ins · " +
    rec.diffStats.deletedTokens + " del · " + rec.diffStats.keptTokens + " kept</span></div>";
}

