functions.showClauseDiffLab:
function showClauseDiffLab(eli) {
  var host = (eli && eli.ui && typeof eli.ui.claimOutput === "function")
    ? eli.ui.claimOutput()
    : document.getElementById("output");
  if (!host) return;

  host.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_cdl_root";
  host.appendChild(root);

  root.innerHTML =
    '<div class="_cdl_header">' +
      '<div class="_cdl_eyebrow">ADMIN · NEGOTIATION CAPTURE TEST</div>' +
      '<div class="_cdl_title">🧪 Clause Diff Lab</div>' +
      '<div class="_cdl_sub">Paste or load an <b>Original</b> (your standard / baseline) and a <b>Final</b> (the executed contract). ' +
      'ELI segments both into clauses, aligns them, and stores a diff record per clause in IDB — then shows you exactly what was saved plus a redline reconstruction.</div>' +
    "</div>" +
    '<div class="_cdl_inputs">' +
      '<div class="_cdl_col">' +
        '<div class="_cdl_collabel">ORIGINAL <span class="_cdl_dim">(baseline)</span>' +
          '<button class="_cdl_btn _cdl_btn_ghost _cdl_btn_sm" id="_cdl_load_orig" title="Load the current Word document into this box">⬇ Load current doc</button>' +
        "</div>" +
        '<textarea class="_cdl_ta" id="_cdl_orig" placeholder="Paste your standard / template text here, or load the current Word doc…"></textarea>' +
      "</div>" +
      '<div class="_cdl_col">' +
        '<div class="_cdl_collabel">FINAL <span class="_cdl_dim">(executed)</span>' +
          '<button class="_cdl_btn _cdl_btn_ghost _cdl_btn_sm" id="_cdl_load_final" title="Load the current Word document into this box">⬇ Load current doc</button>' +
        "</div>" +
        '<textarea class="_cdl_ta" id="_cdl_final" placeholder="Paste the final / negotiated contract here, or load the current Word doc…"></textarea>' +
      "</div>" +
    "</div>" +
    '<div class="_cdl_controls">' +
      '<label class="_cdl_thresh">Match threshold ' +
        '<input type="range" id="_cdl_thresh" min="0.2" max="0.9" step="0.05" value="0.4">' +
        '<span id="_cdl_thresh_val">0.40</span></label>' +
      '<div class="_cdl_controls_actions">' +
        '<button class="_cdl_btn _cdl_btn_primary" id="_cdl_run">⚖ Run Diff &amp; Capture</button>' +
        '<button class="_cdl_btn _cdl_btn_ghost" id="_cdl_view_saved">📦 View saved (IDB)</button>' +
        '<button class="_cdl_btn _cdl_btn_ghost" id="_cdl_clear_saved">🗑 Clear test records</button>' +
      "</div>" +
    "</div>" +
    '<div class="_cdl_status" id="_cdl_status"></div>' +
    '<div class="_cdl_results" id="_cdl_results"></div>';

  var origEl = root.querySelector("#_cdl_orig");
  var finalEl = root.querySelector("#_cdl_final");
  var resultsEl = root.querySelector("#_cdl_results");
  var statusEl = root.querySelector("#_cdl_status");
  var threshEl = root.querySelector("#_cdl_thresh");
  var threshVal = root.querySelector("#_cdl_thresh_val");

  function _status(msg, kind) {
    statusEl.textContent = msg || "";
    statusEl.className = "_cdl_status" + (kind ? " _cdl_status_" + kind : "");
  }

  threshEl.oninput = function () { threshVal.textContent = Number(threshEl.value).toFixed(2); };

  function _loadDoc(targetEl, label) {
    if (!eli.host || typeof eli.host.readText !== "function") {
      _status("Word host unavailable.", "err"); return;
    }
    _status("Reading current document…");
    eli.host.readText({}).then(function (txt) {
      targetEl.value = txt || "";
      _status("Loaded " + (txt ? txt.length : 0) + " chars into " + label + ".", "ok");
    }).catch(function (e) {
      _status("Load failed: " + (e && e.message || "unknown"), "err");
    });
  }
  root.querySelector("#_cdl_load_orig").onclick = function () { _loadDoc(origEl, "Original"); };
  root.querySelector("#_cdl_load_final").onclick = function () { _loadDoc(finalEl, "Final"); };

  root.querySelector("#_cdl_run").onclick = function () {
    var orig = origEl.value || "", final = finalEl.value || "";
    if (!orig.trim() || !final.trim()) {
      _status("Fill in both Original and Final first.", "warn"); return;
    }
    var nowTs = (eli.now && eli.now()) || _cdlNowFallback();
    var result;
    try {
      result = _cdlAnalyze(orig, final, {
        sessionTs: nowTs,
        threshold: Number(threshEl.value),
        toolVersion: "test",
        kernelVersion: (eli && eli.kernelVersion) || "",
        timestamp: nowTs,
      });
    } catch (e) {
      _status("Diff failed: " + (e && e.message || "unknown"), "err");
      try { eli.log.event("tool", "clause_diff_lab_analyze_failed", { msg: e && e.message }); } catch (_e) {}
      return;
    }
    // Persist every record to the negotiation_log store.
    var puts = result.items.map(function (rec) {
      return eli.storage.put("negotiation_log", rec).catch(function (e) {
        try { eli.log.event("tool", "clause_diff_lab_put_failed", { id: rec.id, msg: e && e.message }); } catch (_e) {}
      });
    });
    Promise.all(puts).then(function () {
      _status("Captured " + result.items.length + " clause record(s) to IDB (negotiation_log).", "ok");
    });
    _renderResults(result);
  };

  root.querySelector("#_cdl_view_saved").onclick = function () { _renderSaved(); };
  root.querySelector("#_cdl_clear_saved").onclick = function () {
    eli.ui.confirm({
      title: "Clear test records?",
      message: "Delete all clause_diff_lab records (ids starting cdl_) from the negotiation_log IDB store? This does not touch any other data.",
      confirmText: "Delete", cancelText: "Cancel",
    }).then(function (ok) {
      if (!ok) return;
      eli.storage.getAll("negotiation_log").then(function (rows) {
        var mine = (rows || []).filter(function (r) { return r && typeof r.id === "string" && r.id.indexOf("cdl_") === 0; });
        return Promise.all(mine.map(function (r) { return eli.storage.delete("negotiation_log", r.id); }))
          .then(function () { _status("Deleted " + mine.length + " test record(s).", "ok"); resultsEl.innerHTML = ""; });
      });
    });
  };

  // ── Results render ──
  function _badge(state) {
    var map = {
      unchanged: ["UNCHANGED", "_cdl_b_unch"],
      modified: ["MODIFIED", "_cdl_b_mod"],
      added: ["ADDED", "_cdl_b_add"],
      omitted: ["OMITTED", "_cdl_b_omit"],
    };
    var m = map[state] || [state.toUpperCase(), ""];
    return '<span class="_cdl_badge ' + m[1] + '">' + m[0] + "</span>";
  }

  function _renderResults(result) {
    var c = result.counts;
    var html =
      '<div class="_cdl_summary">' +
        '<div class="_cdl_sumtile"><div class="_cdl_sumn">' + result.origCount + "</div><div class='_cdl_suml'>orig clauses</div></div>" +
        '<div class="_cdl_sumtile"><div class="_cdl_sumn">' + result.finalCount + "</div><div class='_cdl_suml'>final clauses</div></div>" +
        '<div class="_cdl_sumtile _cdl_t_mod"><div class="_cdl_sumn">' + c.modified + "</div><div class='_cdl_suml'>modified</div></div>" +
        '<div class="_cdl_sumtile _cdl_t_add"><div class="_cdl_sumn">' + c.added + "</div><div class='_cdl_suml'>added</div></div>" +
        '<div class="_cdl_sumtile _cdl_t_omit"><div class="_cdl_sumn">' + c.omitted + "</div><div class='_cdl_suml'>omitted</div></div>" +
        '<div class="_cdl_sumtile _cdl_t_unch"><div class="_cdl_sumn">' + c.unchanged + "</div><div class='_cdl_suml'>unchanged</div></div>" +
      "</div>";
    result.items.forEach(function (rec) {
      html += _cdlRenderCard(rec);
    });
    resultsEl.innerHTML = html;
    _wireCards(resultsEl);
  }

  function _renderSaved() {
    _status("Loading saved records…");
    eli.storage.getAll("negotiation_log").then(function (rows) {
      var mine = (rows || []).filter(function (r) { return r && typeof r.id === "string" && r.id.indexOf("cdl_") === 0; });
      if (!mine.length) { resultsEl.innerHTML = '<div class="_cdl_empty">No saved test records yet. Run a diff first.</div>'; _status("0 saved.", "ok"); return; }
      // newest session first
      mine.sort(function (a, b) { return String(b.id).localeCompare(String(a.id)); });
      var html = '<div class="_cdl_savedhdr">' + mine.length + ' record(s) in IDB (negotiation_log, id starts "cdl_")</div>';
      mine.forEach(function (rec) { html += _cdlRenderCard(rec); });
      resultsEl.innerHTML = html;
      _wireCards(resultsEl);
      _status(mine.length + " saved record(s).", "ok");
    }).catch(function (e) { _status("Load failed: " + (e && e.message || "unknown"), "err"); });
  }

  function _wireCards(scope) {
    Array.prototype.forEach.call(scope.querySelectorAll("[data-cdl-toggle]"), function (b) {
      b.onclick = function () {
        var card = b.closest("._cdl_card");
        var which = b.getAttribute("data-cdl-toggle");
        Array.prototype.forEach.call(card.querySelectorAll("._cdl_pane"), function (p) {
          p.style.display = (p.getAttribute("data-cdl-pane") === which) ? "block" : "none";
        });
        Array.prototype.forEach.call(card.querySelectorAll("[data-cdl-toggle]"), function (x) {
          x.classList.toggle("_cdl_seg_active", x === b);
        });
      };
    });
  }
}

// Card markup is shared by fresh-diff + saved-view, so it lives outside the
// closure (top-level fn → window). Renders redline pane + saved-record JSON.

functions._cdlRenderCard:
function _cdlRenderCard(rec) {
  function badge(state) {
    var map = {
      unchanged: ["UNCHANGED", "_cdl_b_unch"], modified: ["MODIFIED", "_cdl_b_mod"],
      added: ["ADDED", "_cdl_b_add"], omitted: ["OMITTED", "_cdl_b_omit"],
    };
    var m = map[state] || [String(state).toUpperCase(), ""];
    return '<span class="_cdl_badge ' + m[1] + '">' + m[0] + "</span>";
  }
  // Durable record = everything except the _test scaffolding.
  var durable = {};
  Object.keys(rec).forEach(function (k) { if (k !== "_test") durable[k] = rec[k]; });
  var sim = rec.state === "modified" || rec.state === "unchanged"
    ? ' <span class="_cdl_dim">sim ' + (rec.similarity != null ? rec.similarity : "—") + "</span>" : "";

  return '<div class="_cdl_card _cdl_card_' + rec.state + '">' +
    '<div class="_cdl_cardhdr">' + badge(rec.state) +
      '<span class="_cdl_cardtitle">' + _cdlEsc(rec.heading || "(untitled)") + "</span>" + sim +
      '<span class="_cdl_cardid">' + _cdlEsc(rec.id) + "</span>" +
    "</div>" +
    '<div class="_cdl_seg">' +
      '<button class="_cdl_segbtn _cdl_seg_active" data-cdl-toggle="redline">Redline</button>' +
      '<button class="_cdl_segbtn" data-cdl-toggle="record">Saved record</button>' +
      '<button class="_cdl_segbtn" data-cdl-toggle="raw">Raw text</button>' +
    "</div>" +
    '<div class="_cdl_pane" data-cdl-pane="redline" style="display:block;">' + _cdlRenderRedline(rec) + "</div>" +
    '<div class="_cdl_pane" data-cdl-pane="record" style="display:none;">' +
      '<div class="_cdl_recordcap">This is exactly what is stored in IDB. <b>_test</b> (raw clause text) is scaffolding for this lab only — in the real system it stays local and is never shared.</div>' +
      '<pre class="_cdl_json">' + _cdlEsc(JSON.stringify(durable, null, 2)) + "</pre>" +
    "</div>" +
    '<div class="_cdl_pane" data-cdl-pane="raw" style="display:none;">' +
      '<div class="_cdl_rawgrid">' +
        '<div><div class="_cdl_rawlbl">ORIGINAL</div><pre class="_cdl_raw">' + _cdlEsc(rec._test ? rec._test.origText : "") + "</pre></div>" +
        '<div><div class="_cdl_rawlbl">FINAL</div><pre class="_cdl_raw">' + _cdlEsc(rec._test ? rec._test.finalText : "") + "</pre></div>" +
      "</div>" +
    "</div>" +
  "</div>";
}

functions._cdlNowFallback:
function _cdlNowFallback() {
  // eli.now() is the blessed timestamp source; this is a defensive fallback
  // only (kernel disallows Date.now in some contexts but tools run in the
  // browser where it's fine).
  try { return Date.now(); } catch (e) { return 0; }
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.register) return;

  function _open() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedClauseDiffLab"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showClauseDiffLab !== "function") {
      eli.log.event("tool", "clause_diff_lab_fn_missing", {});
      if (typeof showToast === "function") showToast("Clause Diff Lab failed to load", "err");
      return;
    }
    try { window.showClauseDiffLab(eli); }
    catch (e) {
      eli.log.event("tool", "clause_diff_lab_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  eli.register({ tile: { app_clause_diff_lab: _open } });
  eli.log.event("tool", "clause_diff_lab_initialized", {});
}

